import { test, expect } from '../fixtures/test-base';

test.describe('Inbox View', () => {
	test.beforeEach(async ({ page, daemon }) => {
		await page.goto('/inbox');
		// Wait for page to load
		await expect(page.getByRole('heading', { name: 'Inbox' })).toBeVisible();
	});

	// ── AC: @ui-inbox-enhanced ac-1 — Triage status inline ──

	// AC: @ui-inbox-enhanced ac-1
	test('displays triage status inline for each inbox item', async ({ page }) => {
		const inboxList = page.getByTestId('inbox-list');
		await expect(inboxList).toBeVisible({ timeout: 10000 });

		const items = page.getByTestId('inbox-item');
		const count = await items.count();
		expect(count).toBeGreaterThan(0);

		// Each item should have a triage status badge
		for (let i = 0; i < count; i++) {
			const item = items.nth(i);
			const statusBadge = item.getByTestId('inbox-triage-status');
			await expect(statusBadge).toBeVisible();

			// Status must be one of the valid labels
			const statusText = await statusBadge.textContent();
			expect(['Untriaged', 'Triaged', 'Acted On']).toContain(statusText?.trim());
		}
	});

	// AC: @ui-inbox-enhanced ac-1
	test('shows correct triage status per item based on fixture data', async ({ page }) => {
		const inboxList = page.getByTestId('inbox-list');
		await expect(inboxList).toBeVisible({ timeout: 10000 });

		// First item (fixture: triaged/defer) should show "Triaged"
		const firstItem = page.getByTestId('inbox-item').filter({ hasText: 'First inbox item' });
		await expect(firstItem.getByTestId('inbox-triage-status')).toHaveText('Triaged');
		// Should show action type
		await expect(firstItem.getByTestId('inbox-triage-action')).toHaveText('defer');

		// Second item (fixture: acted_on/promote) should show "Acted On"
		const secondItem = page.getByTestId('inbox-item').filter({ hasText: 'Second inbox item' });
		await expect(secondItem.getByTestId('inbox-triage-status')).toHaveText('Acted On');
		await expect(secondItem.getByTestId('inbox-triage-action')).toHaveText('promote');

		// Third item (fixture: pending → untriaged) should show "Untriaged"
		const thirdItem = page.getByTestId('inbox-item').filter({ hasText: 'Third inbox item' });
		await expect(thirdItem.getByTestId('inbox-triage-status')).toHaveText('Untriaged');
	});

	// AC: @ui-inbox-enhanced ac-1
	test('shows quick triage link for untriaged items', async ({ page }) => {
		const inboxList = page.getByTestId('inbox-list');
		await expect(inboxList).toBeVisible({ timeout: 10000 });

		// Third item (untriaged) should have a triage link
		const untriagedItem = page.getByTestId('inbox-item').filter({ hasText: 'Third inbox item' });
		await expect(untriagedItem.getByTestId('inbox-triage-link')).toBeVisible();

		// Triaged items should NOT have a triage link
		const triagedItem = page.getByTestId('inbox-item').filter({ hasText: 'First inbox item' });
		await expect(triagedItem.getByTestId('inbox-triage-link')).not.toBeVisible();
	});

	// ── AC: @ui-inbox-enhanced ac-2 — Filter controls ──

	// AC: @ui-inbox-enhanced ac-2
	test('displays filter controls for status, tags, and age', async ({ page }) => {
		const filters = page.getByTestId('inbox-filters');
		await expect(filters).toBeVisible();

		// Status filter
		await expect(page.getByTestId('inbox-status-filter')).toBeVisible();

		// Age filter
		await expect(page.getByTestId('inbox-age-filter')).toBeVisible();

		// Tag filter should appear when items have tags
		const inboxList = page.getByTestId('inbox-list');
		await expect(inboxList).toBeVisible({ timeout: 10000 });
		await expect(page.getByTestId('inbox-tag-filter')).toBeVisible();
