    83→  status: 'pending' | 'in_progress' | 'completed';
    84→  created_at: string;
    85→}
    86→
    87→/**
    88→ * Spec item summary for list endpoints
    89→ * AC: @api-contract ac-8
    90→ */
    91→export interface ItemSummary {
    92→  _ulid: string;
    93→  slugs: string[];
    94→  title: string;
    95→  type: string;
    96→  status?: string;
    97→  tags: string[];
    98→  parent?: string;
    99→  created_at: string;
   100→}
   101→
   102→/**
   103→ * Full spec item with ACs and traits
   104→ * AC: @api-contract ac-10
   105→ */
   106→export interface ItemDetail extends ItemSummary {
   107→  description?: string;
   108→  acceptance_criteria: AcceptanceCriterion[];
   109→  traits: string[];
   110→  depends_on: string[];
   111→  priority?: number;
   112→}
   113→
   114→/**
   115→ * Acceptance criterion
   116→ */
   117→export interface AcceptanceCriterion {
   118→  _ulid: string;
   119→  given: string;
   120→  when: string;
   121→  then: string;
   122→  /** Test coverage status: true=covered, false=not covered, undefined=unknown */
   123→  covered?: boolean;
   124→}
   125→
   126→/**
   127→ * Inbox item
   128→ * AC: @api-contract ac-12
   129→ */
   130→export interface InboxItem {
   131→  _ulid: string;
   132→  text: string;
   133→  tags: string[];
   134→  added_by: string;
   135→  created_at: string;
   136→}
   137→
   138→/**
   139→ * Session context
   140→ * AC: @api-contract ac-15
   141→ */
   142→export interface SessionContext {
   143→  focus?: string;
   144→  threads: string[];
   145→  open_questions: string[];
   146→  updated_at: string;
   147→}
   148→
   149→/**
   150→ * Agent definition
   151→ * AC: @api-contract ac-16
   152→ */
   153→export interface Agent {
   154→  _ulid: string;
   155→  slugs: string[];
   156→  role: string;
   157→  status: string;
   158→  capabilities: string[];
   159→  constraints: string[];
   160→}
   161→
   162→/**
   163→ * Workflow definition
   164→ * AC: @api-contract ac-17
   165→ */
   166→export interface Workflow {
   167→  _ulid: string;
   168→  slugs: string[];
   169→  name: string;
   170→  steps: WorkflowStep[];
   171→}
   172→
   173→/**
   174→ * Workflow step
   175→ */
   176→export interface WorkflowStep {
   177→  _ulid: string;
   178→  type: 'action' | 'check' | 'decision';
   179→  content: string;
   180→}
   181→
   182→/**
   183→ * Observation
   184→ * AC: @api-contract ac-18
   185→ */
   186→export interface Observation {
   187→  _ulid: string;
   188→  type: 'friction' | 'success' | 'question' | 'idea';
   189→  content: string;
   190→  context?: string;
   191→  created_at: string;
   192→  resolved?: boolean;
   193→  resolution?: string;
   194→}
   195→
   196→/**
   197→ * Search result
   198→ * AC: @api-contract ac-19
   199→ * AC: @web-dashboard ac-24
   200→ */
   201→export interface SearchResult {
   202→  type: 'item' | 'task' | 'inbox' | 'observation' | 'agent' | 'workflow' | 'convention';
   203→  ulid: string;
   204→  title: string;
   205→  matchedFields: string[];
   206→}
   207→
   208→/**
   209→ * Search response
   210→ * AC: @api-contract ac-19
   211→ * AC: @web-dashboard ac-24
   212→ */
   213→export interface SearchResponse {
   214→  results: SearchResult[];
   215→  total: number;
   216→  showing: number;
   217→}
   218→
   219→/**
   220→ * Validation result
   221→ * AC: @api-contract ac-20
   222→ */
   223→export interface ValidationResult {
   224→  valid: boolean;
   225→  errors: ValidationError[];
   226→  warnings: ValidationWarning[];
   227→}
   228→
   229→/**
   230→ * Validation error
   231→ */
   232→export interface ValidationError {
   233→  file: string;
   234→  field: string;
   235→  message: string;
   236→  ref?: string;
   237→}
   238→
   239→/**
   240→ * Validation warning
   241→ */
   242→export interface ValidationWarning {
   243→  file: string;
   244→  message: string;
   245→  ref?: string;
   246→}
   247→
   248→/**
   249→ * Alignment index stats
   250→ * AC: @api-contract ac-21
   251→ */
   252→export interface AlignmentStats {
   253→  total_specs: number;
   254→  total_tasks: number;
   255→  specs_without_tasks: number;
   256→  tasks_without_specs: number;
   257→  warnings: string[];
   258→}
   259→
   260→/**
   261→ * Convention definition from meta manifest
   262→ */
   263→export interface Convention {
   264→  _ulid: string;
   265→  domain: string;
   266→  rules: string[];
   267→  examples?: Array<{ good: string; bad: string }>;
   268→  validation?: {
   269→    type: 'regex' | 'enum' | 'range' | 'prose';
   270→    pattern?: string;
   271→    message?: string;
   272→    allowed?: string[];
   273→    min?: number;
   274→    max?: number;
   275→    unit?: 'words' | 'chars' | 'lines';
   276→  };
   277→}
   278→
   279→/**
   280→ * Triage status lifecycle
   281→ */
   282→export type TriageStatus = 'pending' | 'triaged' | 'acted_on';
   283→
   284→/**
   285→ * Triage action types
   286→ */
   287→export type TriageAction = 'promote' | 'delete' | 'defer' | 'spec-gap' | 'duplicate';
   288→
   289→/**
   290→ * Triage record
   291→ */
   292→export interface TriageRecord {
   293→  _ulid: string;
   294→  inbox_ref: string;
   295→  item_snapshot: string;
   296→  status: TriageStatus;
   297→  action?: TriageAction;
   298→  reasoning?: string;
   299→  decided_by?: string;
   300→  evidence_refs: string[];
   301→  override_reasoning?: string;
   302→  override_by?: string;
   303→  override_at?: string;
   304→  acted_at?: string;
   305→  result_ref?: string;
   306→  created_at: string;
   307→  updated_at?: string;
   308→}
   309→
   310→/**
   311→ * Acceptance criterion with inheritance tracking
   312→ */
   313→export interface InheritedAC extends AcceptanceCriterion {
   314→  _inherited_from: string;
   315→}
   316→
   317→/**
   318→ * Exported task with resolved spec reference title
   319→ */
   320→export interface ExportedTask extends TaskDetail {
   321→  spec_ref_title?: string;
   322→}
   323→
   324→/**
   325→ * Exported spec item with nested hierarchy and inherited ACs.
   326→ * Note: extends ItemDetail (acceptance_criteria required) because the JSON
   327→ * snapshot always includes the field. The core export module uses Omit to
   328→ * build from parser types where AC may not yet exist, but by the time data
   329→ * reaches the web-ui via snapshot, AC is always present (at least as []).
   330→ */
   331→export interface ExportedItem extends ItemDetail {
   332→  children?: ExportedItem[];
   333→  inherited_acs?: InheritedAC[];
   334→}
   335→
   336→/**
   337→ * Project metadata in a snapshot
   338→ */
   339→export interface ExportedProject {
   340→  name: string;
   341→  version?: string;
   342→  description?: string;
   343→}
   344→
   345→/**
   346→ * Validation result included in a snapshot
   347→ */
   348→export interface ExportedValidation {
   349→  valid: boolean;
   350→  errorCount: number;
   351→  warningCount: number;
   352→  errors: Array<{
   353→    file: string;
   354→    message: string;
   355→    path?: string;
   356→  }>;
   357→  warnings: Array<{
   358→    file: string;
   359→    message: string;
   360→  }>;
   361→}
   362→
   363→/**
   364→ * Full kspec snapshot structure
   365→ */
   366→export interface KspecSnapshot {
   367→  version: string;
   368→  exported_at: string;
   369→  project: ExportedProject;
   370→  tasks: ExportedTask[];
   371→  items: ExportedItem[];
   372→  inbox: InboxItem[];
   373→  session: SessionContext | null;
   374→  observations: Observation[];
   375→  agents: Agent[];
   376→  workflows: Workflow[];
   377→  conventions: Convention[];
   378→  validation?: ExportedValidation;
   379→}
   380→
